triggered := false
if (any(#Window).weatherProvider.Weather == "rain") {
if (triggered == false) {
hold_ticks := 0
        if (any(#Window).windowCovering.CurrentPosition == 0) {
hold_ticks = hold_ticks + 1
            if (hold_ticks >= 180) {
all(#Window).windowCovering_downOrClose()
                triggered = true
}
}
else {
hold_ticks = 0
}
}
else {
triggered = false
}
}
else {
triggered = false
}

